$Results = @("F7DC14C4A4CB293B12A16892C8CF032B0467C727E9E1329A5EF3EF272590B93E")

try {
    if (-not (Test-Path -LiteralPath $Path)) {
        Write-Host "WoWClient.exe was not found: $Path" -ForegroundColor Red
        Write-Host "Put patch.bat and patch.ps1 in the game folder (next to WoWClient.exe)."
        exit 1
    }
    $Path = (Resolve-Path -LiteralPath $Path).Path
    $data = [System.IO.File]::ReadAllBytes($Path)
    $hash = Get-Sha256 $data
    Write-Host "File:   $Path"
    Write-Host "SHA256: $hash"

    if ($Results -contains $hash) {
        Write-Host "This WoWClient.exe is already patched. Nothing to do." -ForegroundColor Green
        exit 0
    }
    if (-not $Known.ContainsKey($hash)) {
        Write-Host "Unknown WoWClient.exe - nothing was changed." -ForegroundColor Red
        Write-Host "Please report the SHA256 above so support can be added."
        exit 1
    }
    $entry = $Known[$hash]
    Write-Host "Found:  $($entry.Name)"
    if ($data.Length -ne $entry.Size) { throw "unexpected file size" }

    if ($entry.Append.Length -gt 0) {
        $extra = Convert-Hex $entry.Append
        $grown = New-Object byte[] ($data.Length + $extra.Length)
        [System.Array]::Copy($data, 0, $grown, 0, $data.Length)
        [System.Array]::Copy($extra, 0, $grown, $data.Length, $extra.Length)
        $data = $grown
    }
    foreach ($p in $entry.Patches) {
        $offset = [int]$p[0]
        $bytes = Convert-Hex $p[1]
        [System.Array]::Copy($bytes, 0, $data, $offset, $bytes.Length)
    }
    $newHash = Get-Sha256 $data
    if ($newHash -ne $entry.Result) {
        throw "the patched file does not match the expected result ($newHash)"
    }

    $dir = Split-Path -Parent $Path
    $backup = Join-Path $dir "WoWClient_before_patch.exe"
    if (-not (Test-Path -LiteralPath $backup)) {
        Copy-Item -LiteralPath $Path -Destination $backup
        Write-Host "Backup: $backup"
    } else {
        Write-Host "Backup already exists, kept: $backup"
    }
    [System.IO.File]::WriteAllBytes($Path, $data)
    Write-Host "Done. WoWClient.exe is patched (SHA256 $newHash)." -ForegroundColor Green
    $gmodHere = Join-Path $dir "gmod.dll"
    $gmodPack = Join-Path $PSScriptRoot "gmod.dll"
    if (-not (Test-Path -LiteralPath $gmodHere) -and (Test-Path -LiteralPath $gmodPack)) {
        if ((Get-Sha256 ([System.IO.File]::ReadAllBytes($gmodPack))) -eq "34BFAF05CCA3395A6FC2C8D57C14ED428FA2C9FE9546FFB035884DE45A6C1FB2") {
            Copy-Item -LiteralPath $gmodPack -Destination $gmodHere
            Write-Host "gmod.dll was missing - the included gmod.dll (by rajkosto) was copied"
            Write-Host "next to WoWClient.exe."
        }
    }
    if (-not (Test-Path -LiteralPath $gmodHere)) {
        Write-Host ""
        Write-Host "WARNING: gmod.dll is missing next to WoWClient.exe." -ForegroundColor Yellow
        Write-Host "The game will not start without it. gmod.dll adds the account name and" -ForegroundColor Yellow
        Write-Host "password fields on the login screen, so it is also needed to log in to" -ForegroundColor Yellow
        Write-Host "0.5.3 servers." -ForegroundColor Yellow
        Write-Host "gmod.dll is included in WoW053_ClientPatch_v5.zip: copy it next to" -ForegroundColor Yellow
        Write-Host "WoWClient.exe. It can also be found in The Alpha Project Discord:" -ForegroundColor Yellow
        Write-Host "https://discord.gg/RzBMAKU" -ForegroundColor Yellow
        Write-Host "To go back to your old WoWClient.exe, use WoWClient_before_patch.exe." -ForegroundColor Yellow
    }

    exit 0
} catch {
    Write-Host "Patch failed, the original file was not changed: $($_.Exception.Message)" -ForegroundColor Red
    exit 1
}
